window.OBJ = [{"code":"A2.5","t":"Die PSA","g":"Ich zähle die Elemente der für die Arbeit geeigneten persönlichen Schutzausrüstung (PSA) auf und erkläre ihre Wirkung, ihre Verwendung und ihre Pflege. (K2)","col":"teal","ic":"helmet","ch":[{"k":"qcm","q":"Wofür steht «PSA»?","a":["Persönliche Schutzausrüstung","Präventions-Sicherheits-Anlage","Persönliche Spezial-Ausrüstung","Produktions-Schutz-Apparat"],"ex":"PSA = persönliche Schutzausrüstung: von einer Person getragen oder gehalten, um sie vor einem oder mehreren Risiken zu schützen.","ref":"Lektion 3.6"},{"k":"multi","q":"Welche davon sind im Kurs genannte PSA?","good":["Schutzhelm","Schutzhandschuhe","Sicherheitsschuhe","Warnweste","Gehörschutz"],"bad":["Sonnenbrille","Turnschuhe"],"ex":"Gewöhnliche Brillen oder Schuhe sind keine PSA: Es braucht zertifizierte Sicherheitsausrüstung.","ref":"Lektion 3.6"},{"k":"tf","q":"Gewöhnliche «Schuhe» sind eine PSA.","v":false,"ex":"«Schuhe» ≠ PSA; «zertifizierte Sicherheitsschuhe» = PSA.","ref":"Lektion 3.6"},{"k":"tf","q":"PSA werden eingesetzt, wenn die Risiken nicht an der Quelle beseitigt werden können.","v":true,"ex":"Zuerst beseitigt man die Gefahr; die PSA schützt vor dem, was bleibt.","ref":"Lektion 3.6"},{"k":"case","s":"Der Chef eines Lernenden sagt ihm, er solle seine Schnittschutzhandschuhe bis Montag selbst kaufen.","q":"Wer muss die geeignete PSA zur Verfügung stellen?","a":["Der Arbeitgeber","Der Arbeitnehmer selbst","Die Suva","Der Warenlieferant"],"ex":"Der Arbeitgeber stellt die geeignete PSA zur Verfügung; die Arbeitnehmenden müssen sie korrekt verwenden.","ref":"Lektion 3.6"},{"k":"qcm","q":"Was zeigt ein rundes Schild mit blauem Grund an?","a":["Ein Gebot, das zwingend einzuhalten ist","Ein Verbot, die Zone zu betreten","Eine Gefahr in unmittelbarer Nähe","Einen Notausgang oder Fluchtweg"],"ex":"Runde Schilder mit blauem Grund sind Gebotszeichen: zum Beispiel Helm oder Schutzbrille tragen.","ref":"Lektion 3.6"},{"k":"pickimg","q":"Welches Schild schreibt das Tragen von Schutzhandschuhen vor?","a":["p_gants","p_casque","p_lunettes","p_chaussures"],"ex":"Gebotszeichen: Schutzhandschuhe.","ref":"Lektion 3.6"},{"k":"pickimg","q":"Welches Schild schreibt das Tragen einer Schutzbrille vor?","a":["p_lunettes","p_casque","p_gants","p_chaussures"],"ex":"Gebotszeichen: Schutzbrille.","ref":"Lektion 3.6"},{"k":"case","s":"Sie betreten eine Zone mit einem runden blauen Schild mit Helm. Sie bleiben «nur zwei Minuten».","q":"Was tun Sie?","a":["Ich setze den Helm beim Betreten der Zone auf","Ich gehe ohne Helm hinein, weil es sehr kurz ist","Ich trage den Helm für alle Fälle in der Hand","Ich warte, bis mir ein Kollege sagt, ich solle ihn aufsetzen"],"ex":"Jede Person, die die gekennzeichnete Zone betritt, befolgt die Anweisung sofort.","ref":"Lektion 3.6"},{"k":"match","q":"Ordnen Sie jeder Handschuhart ihren Einsatz zu.","p":[["Schnittschutz","Stahlumreifungen aufschneiden"],["Leder","Holzpaletten tragen"],["Latex oder Nitril","Leichte Chemikalien handhaben"]],"ex":"Man wählt die Handschuhe passend zum Risiko.","ref":"Lektion 3.6"},{"k":"qcm","q":"Mit welchen Fasern sind Schnittschutzhandschuhe oft verstärkt?","a":["Kevlar oder Dyneema","Baumwolle oder Wolle","Latex oder Gummi","Leinen oder Hanf"],"ex":"Technische Fasern wie Kevlar oder Dyneema widerstehen Schnitten.","ref":"Lektion 3.6"},{"k":"case","s":"Sie müssen nasse und schmutzige Abfälle sortieren, von denen einige gefährliche Stoffe enthalten könnten.","q":"Welche Handschuhe wählen Sie?","a":["Handschuhe aus Latex oder Nitril","Lederhandschuhe","Schnittschutzhandschuhe","Keine, ich wasche danach die Hände"],"ex":"Latex oder Nitril: Schutz vor Flüssigkeiten und verschmutzenden oder gefährlichen Produkten.","ref":"Lektion 3.6"},{"k":"case","s":"Sie müssen schwere, raue Rohholzplatten stapeln.","q":"Welche Handschuhe sind am besten geeignet?","a":["Lederhandschuhe","Dünne Latexhandschuhe","Nitril-Einweghandschuhe","Wollhandschuhe"],"ex":"Leder ist abriebfest und schützt vor mechanischen Risiken.","ref":"Lektion 3.6"},{"k":"sort","q":"Ordnen Sie jede Aufgabe den passenden Handschuhen zu.","c":["Schnittschutz","Leder","Latex/Nitril"],"it":[["Bleche handhaben",0],["Eine Holzkiste öffnen",1],["Ein auslaufendes Paket handhaben",2],["Mit Glas arbeiten",0],["Paletten sortieren",1],["Ein Reinigungsmittel handhaben",2]],"ex":"Schnitt → Schnittschutz; Reibung und Lasten → Leder; Flüssigkeiten und Chemie → Latex oder Nitril.","ref":"Lektion 3.6"},{"k":"case","s":"Man schickt Sie an die Aussenrampe, wo ein Kran Träger von einem Lastwagen ablädt. Im Lager tragen Sie nie einen Helm.","q":"Wann ist das Tragen eines Helms in der Logistik nötig?","a":["Unter Kranlasten und beim Rangieren","In allen Büros und Garderoben des Unternehmens","Nur während der jährlichen Inventur","Nur wenn es auf die Verladerampe regnet"],"ex":"Der Helm ist in der Logistik selten Pflicht, aber nötig unter Kranlasten oder beim Rangieren.","ref":"Lektion 3.6"},{"k":"tf","q":"Beim Rangieren ist das Tragen einer Warnweste Pflicht.","v":true,"ex":"Der Kurs sagt es für den Rangierdienst.","ref":"Lektion 3.6"},{"k":"case","s":"Sie müssen den Säurestand der Batterie eines Gabelstaplers kontrollieren.","q":"Welche PSA ist unerlässlich?","a":["Eine Schutzbrille","Ein Kapselgehörschutz","Eine Warnweste","Strassenschuhe"],"ex":"Die Brille schützt vor Spritzern ätzender Stoffe.","ref":"Lektion 3.6"},{"k":"multi","q":"Welche PSA muss man tragen, um ein Umreifungsband aufzuschneiden?","good":["Schutzbrille","Schutzhandschuhe"],"bad":["Kapselgehörschutz","Warnweste"],"ex":"Der Kurs nennt Schutzbrille und Schutzhandschuhe.","ref":"Lektion 3.6"},{"k":"fill","q":"Damit eine Brille eine PSA ist, muss sie als Brille für die ___ zertifiziert sein.","a":["Sicherheit","Sonne","Sehkorrektur","Lektüre"],"ex":"«Brille» ≠ PSA; «zertifizierte Schutzbrille» = PSA.","ref":"Lektion 3.6"},{"k":"odd","q":"Was ist keine PSA?","a":["Ein Paar Sport-Turnschuhe","Ein Kapselgehörschutz","Sicherheitsschuhe","Eine Warnweste"],"ex":"Turnschuhe sind keine zertifizierte Ausrüstung.","ref":"Lektion 3.6"},{"k":"case","s":"Ihre Schnittschutzhandschuhe haben beim Daumen ein Loch.","q":"Was tun Sie?","a":["Ich ersetze sie, bevor ich weiterschneide","Ich mache weiter: Der Rest des Handschuhs schützt noch","Ich klebe Klebeband auf das Loch","Ich arbeite ohne Handschuhe, um mehr zu spüren"],"ex":"Eine beschädigte PSA schützt nicht mehr: Sie muss gepflegt und ersetzt werden.","ref":"Lektion 3.6 · Pflege (nicht im Kursmaterial)"},{"k":"tf","q":"Das Tragen von PSA ist je nach Arbeitsplatz und erkannten Risiken oft Pflicht.","v":true,"ex":"Die Arbeitnehmenden müssen sie korrekt verwenden.","ref":"Lektion 3.6"},{"k":"case","s":"Ein neuer Kollege findet seine Sicherheitsschuhe schwer und kommt in Turnschuhen ins Lager.","q":"Was sagen Sie ihm?","a":["Dass Sicherheitsschuhe Pflicht sind und ihn schützen","Dass Turnschuhe genügen, wenn er gut aufpasst","Dass er sie nur zum Fahren eines Geräts anziehen muss","Dass es seine persönliche Wahl ist und nur ihn angeht"],"ex":"Moderne Sicherheitsschuhe sehen aus wie normale Schuhe und verhindern die meisten Fussverletzungen.","ref":"Lektion 3.6"},{"k":"qcm","q":"Warum ist PSA in der Logistik unerlässlich?","a":["Sie beugt Unfällen bei Manipulation und Verkehr vor","Sie ersetzt die Sicherheitsschulung der Neuen","Sie erlaubt vor allem, viel schneller zu arbeiten","Sie dient vor allem dem Image des Unternehmens bei den Kunden"],"ex":"Manipulation, Fahrzeugverkehr und herabfallende Gegenstände: PSA beugt diesen Unfällen vor.","ref":"Lektion 3.6"},{"k":"match","q":"Ordnen Sie jeder PSA den geschützten Körperteil zu.","p":[["Schutzhelm","Kopf"],["Sicherheitsschuhe","Füsse"],["Gehörschutzpfropfen","Gehör"],["Gesichtsschutzschild","Gesicht und Augen"]],"ex":"Jede PSA schützt einen bestimmten Körperteil.","ref":"Lektion 3.6"},{"k":"order","q":"Bringen Sie die richtige Verwendung einer PSA in die richtige Reihenfolge.","a":["Die zum Risiko passende PSA wählen","Ihren Zustand vor dem Gebrauch prüfen","Sie während der Arbeit korrekt tragen","Sie nach dem Gebrauch reinigen","Sie versorgen oder melden, wenn sie beschädigt ist"],"ex":"PSA verwenden heisst auch, sie zu kontrollieren und zu pflegen.","ref":"Lektion 3.6 · Pflege (nicht im Kursmaterial)"},{"k":"case","s":"Ihr Kapselgehörschutz ist schmutzig und ein Polster ist gerissen.","q":"Was tun Sie?","a":["Ich reinige ihn und lasse das Polster ersetzen","Ich werfe ihn weg und arbeite ohne Schutz","Ich leihe ihn einem Kollegen zum Reparieren","Ich behalte ihn so, er schützt noch etwas"],"ex":"Die Pflege der PSA gehört zu ihrer korrekten Verwendung.","ref":"Lektion 3.6 · Pflege (nicht im Kursmaterial)"}]},{"code":"A2.7","t":"Vorbeugende Massnahmen","g":"Ich beschreibe konkrete persönliche Massnahmen zum Schutz von Gesundheit und Umwelt, um Berufskrankheiten zu vermeiden und die Arbeitssicherheit zu gewährleisten. (K2)","col":"indigo","ic":"shield","ch":[{"k":"multi","q":"Welche Vorsichtsmassnahmen nennt der Kurs zum Schutz der Füsse?","good":["Die Füsse nie unter eine angehobene Last stellen","Die Füsse von Rollen und Rädern fernhalten","Nichts am Boden liegen lassen","Die Füsse innerhalb der Kontur des Handwagens halten"],"bad":["Paletten mit dem Fuss schieben","Die Sicherheitsschuhe zum Fahren ausziehen"],"ex":"Das sind die vier Vorsichtsmassnahmen des Kurses.","ref":"Lektion 3.6"},{"k":"case","s":"Sie leiten das Absenken einer von einem Gabelstapler angehobenen Palette. Ihr Fuss ist direkt unter dem Rand der Palette.","q":"Was tun Sie?","a":["Ich ziehe den Fuss sofort unter der Last weg","Ich lasse den Fuss: Meine Schuhe sind sicher","Ich schiebe die Palette mit dem Fuss zurecht","Ich bitte den Staplerfahrer, schneller abzusenken"],"ex":"Die Füsse nie unter angehobene Lasten stellen, auch nicht mit Sicherheitsschuhen.","ref":"Lektion 3.6"},{"k":"qcm","q":"Was verletzt die Füsse von Logistikern oft?","a":["Räder der Wagen und Nägel in Brettern","Die Computerbildschirme im Versandbüro","Die Sonnenstrahlen auf der Rampe im Sommer","Die eisige Kälte im Kühlraum"],"ex":"Räder von Handwagen oder Staplern sowie aus Brettern ragende Nägel.","ref":"Lektion 3.6"},{"k":"order","q":"Bringen Sie das sichere Aufschneiden eines Umreifungsbands in die richtige Reihenfolge.","a":["Brille und Handschuhe anziehen","Die Schnittstelle wählen","Das lange Ende festhalten","Das Band durchschneiden","Die Stücke entsorgen"],"ex":"Man schneidet so, dass ein kurzes und ein langes Ende entsteht, und hält das lange fest, damit es nicht verletzt.","ref":"Lektion 3.6"},{"k":"case","s":"Sie müssen die Stahlumreifung einer Palette mit Blechen aufschneiden.","q":"Wo schneiden Sie?","a":["Kurzes und langes Ende, das lange halte ich","In der Mitte, damit beide Enden weit von mir wegspringen","So nah wie möglich am Gesicht, um den Schnitt gut zu sehen","Irgendwo, Hauptsache, es geht schnell"],"ex":"Das lange Ende wird festgehalten, damit es nicht verletzt.","ref":"Lektion 3.6"},{"k":"tf","q":"Einen leeren Karton zwischen zwei Gängen am Boden liegen zu lassen, ist ungefährlich.","v":false,"ex":"«Nichts am Boden liegen lassen»: Ein Gegenstand am Boden lässt stolpern und kann ein Fahrzeug blockieren.","ref":"Lektion 3.6"},{"k":"qcm","q":"Welche Massnahme kommt nach dem STOP-Prinzip zuerst?","a":["Die Gefahr beseitigen oder ersetzen (Substitution)","Eine persönliche Schutzausrüstung tragen","Das Personal mit einer schriftlichen Anweisung schulen","Die Arbeitszeiten des Teams ändern"],"ex":"STOP: Substitution, Technische, Organisatorische, dann Persönliche Massnahmen (PSA, Ausbildung).","ref":"Nicht im Kursmaterial · SECO, STOP-Prinzip"},{"k":"order","q":"Bringen Sie das STOP-Prinzip in die richtige Reihenfolge.","a":["Substitution","Technische Massnahmen","Organisatorische Massnahmen","Persönliche Massnahmen"],"ex":"Man setzt zuerst bei der Gefahr selbst an; die PSA kommt zuletzt.","ref":"Nicht im Kursmaterial · SECO, STOP-Prinzip"},{"k":"sort","q":"Ordnen Sie jede Massnahme nach dem STOP-Prinzip zu.","c":["Technisch","Organisatorisch","Persönlich"],"it":[["Einen Hubtisch installieren",0],["Die Kommissionierplätze rotieren lassen",1],["Schnittschutzhandschuhe tragen",2],["Ein Rollenförderband einbauen",0],["Regelmässige Pausen vorsehen",1],["Eine Schulung «Heben und Tragen» besuchen",2]],"ex":"Technisch: eine Einrichtung. Organisatorisch: wie die Arbeit organisiert ist. Persönlich: was die Person tut (PSA, Ausbildung).","ref":"Nicht im Kursmaterial · SECO, STOP-Prinzip"},{"k":"case","s":"Sie kommissionieren den ganzen Tag. Am späten Nachmittag spüren Sie Verspannungen im Nacken.","q":"Was tun Sie?","a":["Ich melde es: Das ist ein Zeichen eines ungeeigneten Platzes","Ich ignoriere den Schmerz: Am Abend ist das normal","Ich nehme jeden Tag ein Schmerzmittel und mache weiter","Ich arbeite schneller, um früher fertig zu sein"],"ex":"Verspannungen im Nacken sind eines der ersten Zeichen eines ungeeigneten Arbeitsplatzes.","ref":"Lektion 3.6"},{"k":"multi","q":"Welche persönlichen Massnahmen schützen Ihren Rücken?","good":["Die verfügbaren Hilfsmittel nutzen","Beim Tragen den Rücken gerade halten","Für eine schwere Last Hilfe holen","Sich nicht tief bücken"],"bad":["Beim Heben den Oberkörper drehen","Die Last weit vom Körper tragen"],"ex":"Hilfsmittel, gerader Rücken, Hilfe eines Kollegen.","ref":"Lektion 3.6 · Nicht im Kursmaterial · Suva, «Heben und Tragen»"},{"k":"case","s":"Ein Kollege will eine Holzkiste mit blossen Händen öffnen, «weil ihn die Handschuhe stören».","q":"Was raten Sie ihm?","a":["Widerstandsfähige, zur Aufgabe passende Handschuhe tragen","Auf Splitter achten und ohne Handschuhe arbeiten","Dünne Latexhandschuhe anziehen, die angenehmer sind","Die Kiste jemand anderem im Team überlassen"],"ex":"Holzkisten öffnen gehört zu den Aufgaben, die widerstandsfähige Handschuhe verlangen.","ref":"Lektion 3.6"},{"k":"tf","q":"Die Verpackungen im Lager richtig zu trennen, schützt auch die Umwelt.","v":true,"ex":"Der Umweltschutz gehört zu den persönlichen Massnahmen des Lernziels.","ref":"Lernziel A2.7 (nicht im Kursmaterial)"},{"k":"case","s":"Eine Palette ist kaputt und es ragen Nägel heraus. Sie sind in Eile.","q":"Was tun Sie?","a":["Ich nehme sie aus dem Umlauf und melde sie","Ich lasse sie an der Rampe: Irgendwer kümmert sich darum","Ich verwende sie wieder und meide die Nägel","Ich verstecke sie unter einer intakten Palette"],"ex":"Aus Brettern ragende Nägel verletzen oft die Füsse: Man beseitigt die Gefahrenquelle.","ref":"Lektion 3.6"},{"k":"qcm","q":"Welche Massnahme beugt Rückenschmerzen beim Laden von Paletten am besten vor?","a":["Hilfsmittel wie einen Scherenhubwagen verwenden","Sich tief bücken, um etwas schneller zu sein","Die Lasten mit einem Arm tragen, um den anderen frei zu haben","Die Arbeit allein machen, um keinen Kollegen zu stören"],"ex":"Lasten ohne tiefes Bücken aufnehmen und Hilfsmittel verwenden.","ref":"Lektion 3.6"},{"k":"match","q":"Ordnen Sie jedem Risiko die vorbeugende Massnahme zu.","p":[["Räder des Handwagens","Die Füsse innerhalb der Kontur halten"],["Peitschendes Umreifungsband","Das lange Ende festhalten"],["Batteriesäure","Eine Schutzbrille tragen"],["Schwere Last am Boden","Ein Hilfsmittel verwenden"]],"ex":"Jede Gefahr hat ihre vorbeugende Massnahme.","ref":"Lektion 3.6"},{"k":"odd","q":"Was ist keine vorbeugende Massnahme?","a":["Den Helm abnehmen, um besser zu hören","Sicherheitsschuhe tragen","Den Durchgang freiräumen","Einen Handhubwagen benutzen"],"ex":"Eine vorgeschriebene PSA zieht man nie aus.","ref":"Lektion 3.6"},{"k":"fill","q":"Die Füsse innerhalb der ___ des Handwagens halten.","a":["Kontur","Motorhaube","Ladefläche","Speichen"],"ex":"Die Füsse bleiben innerhalb der Kontur des Wagens, damit sie nicht gequetscht werden.","ref":"Lektion 3.6"},{"k":"case","s":"Ihr Chef bittet Sie, zwischen zwei Massnahmen gegen Schnittverletzungen beim Auspacken zu wählen: Cutter mit Klingenrückzug kaufen oder die Mitarbeitenden an die Vorsicht erinnern.","q":"Welche Massnahme ist am wirksamsten?","a":["Die Cutter mit Klingenrückzug: eine technische Massnahme","Die Erinnerung: Die Vorsicht der Mitarbeitenden genügt immer","Keine: Schnittverletzungen gehören einfach zum Beruf","Jedes Auspacken von Kartons im Lager verbieten"],"ex":"Nach dem STOP-Prinzip kommt eine technische Massnahme vor einer persönlichen.","ref":"Nicht im Kursmaterial · SECO, STOP-Prinzip"},{"k":"tf","q":"Eine Berufskrankheit kann langsam auftreten, nach Jahren schlechter Haltung.","v":true,"ex":"Gewisse Gefahren schädigen den Körper langsam und verursachen chronische Beschwerden.","ref":"Lektion 3.6"},{"k":"qcm","q":"Wofür steht das «T» in STOP?","a":["Technische Massnahmen","Teamarbeit","Tagespausen","Tenue (Arbeitskleidung)"],"ex":"S = Substitution, T = Technik, O = Organisation, P = Person.","ref":"Nicht im Kursmaterial · SECO, STOP-Prinzip"},{"k":"case","s":"Beim Entladen sehen Sie eine Öllache neben dem Rampentor.","q":"Was tun Sie?","a":["Ich sichere die Zone und lasse die Lache reinigen","Ich steige darüber und arbeite an der Rampe weiter","Ich decke sie mit einem leeren Karton ab","Ich melde es erst am Ende meines Arbeitstags"],"ex":"Eine Gefahrenquelle zu beseitigen schützt Sie selbst und die anderen.","ref":"Lektion 3.6"},{"k":"qcm","q":"Warum muss man die Füsse von Rollen und Rädern fernhalten?","a":["Damit sie nicht gequetscht werden","Damit die Schuhe nicht schmutzig werden","Damit die Räder des Wagens nicht abnutzen","Damit man schneller vorwärtskommt"],"ex":"Die Räder der Wagen sind eine häufige Ursache von Fussverletzungen.","ref":"Lektion 3.6"},{"k":"case","s":"Am Schichtende lassen Sie Werkzeuge und Stretchfolie neben Ihrem Platz am Boden liegen.","q":"Welches Risiko schaffen Sie für das nächste Team?","a":["Sturzgefahr oder ein blockiertes Fahrzeug","Keines: Das nächste Team räumt auf","Eine einfache Unordnung ohne Folgen","Ein Risiko nur für das Material"],"ex":"«Nichts am Boden liegen lassen» schützt auch die Kollegen.","ref":"Lektion 3.6"},{"k":"case","s":"Sie handhaben ein auslaufendes Paket, dessen Etikette auf eine Chemikalie hinweist.","q":"Was tun Sie?","a":["Ich ziehe Nitrilhandschuhe an und befolge die Anweisung","Ich trage es mit blossen Händen bis zur Versandrampe","Ich wische es mit meinem üblichen Arbeitslappen ab","Ich lasse es mitten im Gang für den Chef stehen"],"ex":"Latex oder Nitril für Pakete mit Flüssigkeiten oder Chemikalien.","ref":"Lektion 3.6"}]},{"code":"A2.8","t":"Körperliche Belastungen","g":"Ich beschreibe die mit der beruflichen Tätigkeit verbundenen körperlichen Belastungen (Skelett, Gelenke, Muskulatur), ihre Auswirkungen und die vorbeugenden Massnahmen, um sie zu vermeiden oder zu verringern. (K2)","col":"violet","ic":"spine","ch":[{"k":"multi","q":"Woraus besteht die Wirbelsäule laut Kurs?","good":["Wirbel","Bandscheiben","Bänder","Muskeln"],"bad":["Achillessehnen","Knorpel des Knies"],"ex":"Wirbel, Bandscheiben, Bänder und Muskeln.","ref":"Lektion 3.6"},{"k":"multi","q":"Welche Tätigkeiten sind für den Rücken gefährlich?","good":["Das Umpacken","Die Kommissionierung","Das Beladen von Paletten","Das Entladen von Paletten"],"bad":["Das Lesen eines Lieferscheins","Eine Teamsitzung im Sitzen"],"ex":"Der Kurs nennt das Umpacken, die Kommissionierung und das Be- oder Entladen von Paletten.","ref":"Lektion 3.6"},{"k":"qcm","q":"Was ist die korrekte Haltung, um eine Last zu tragen?","a":["Arme gestreckt oder auf den Schultern, Rücken gerade","Last auf einer Hüfte, Oberkörper seitlich geneigt","Last weit vor sich gehalten, Arme angewinkelt","Runder Rücken und gestreckte Beine, um schnell zu sein"],"ex":"Mit gestreckten Armen oder auf den Schultern, mit geradem Rücken.","ref":"Lektion 3.6"},{"k":"case","s":"Sie müssen einen Karton von 15 kg vom Boden aufnehmen.","q":"Wie heben Sie ihn an?","a":["Beine gebeugt, Rücken gerade, Last nahe am Körper","Beine gestreckt, indem ich mich tief bücke","Indem ich den Oberkörper drehe, um schneller zu sein","Mit einer Hand, um die andere frei zu haben"],"ex":"Die Last ohne tiefes Bücken aufnehmen, Rücken gerade, nahe am Körper.","ref":"Lektion 3.6 · Nicht im Kursmaterial · Suva, «Heben und Tragen»"},{"k":"num","q":"Wie hoch ist der Suva-Richtwert für gelegentliches Tragen durch einen Mann von 20 bis 35 Jahren?","n":25,"tol":0,"u":"kg","ex":"25 kg für Männer und 15 kg für Frauen von 20 bis 35 Jahren, bei gelegentlichem Tragen, Last nahe am Körper.","ref":"Nicht im Kursmaterial · Suva, «Heben und Tragen»"},{"k":"num","q":"Wie hoch ist der Suva-Richtwert für gelegentliches Tragen durch eine Frau von 20 bis 35 Jahren?","n":15,"tol":0,"u":"kg","ex":"15 kg für Frauen, 25 kg für Männer.","ref":"Nicht im Kursmaterial · Suva, «Heben und Tragen»"},{"k":"tf","q":"Die Gewichtsrichtwerte sind für Jugendliche unter 18 Jahren tiefer.","v":true,"ex":"Zum Beispiel 19 kg für einen jungen Mann von 16 bis 18 Jahren, 12 kg für eine junge Frau.","ref":"Nicht im Kursmaterial · Suva, «Heben und Tragen»"},{"k":"qcm","q":"Was ist Ergonomie?","a":["Arbeitsplätze anpassen, um Ermüdung zu senken","Das Arbeitstempo des Teams erhöhen","Die Zahl der Pausen am Tag verringern","Günstigere Werkzeuge für das Lager wählen"],"ex":"Die Ergonomie gestaltet geeignete Arbeitsplätze und Werkzeuge, um Ermüdung zu verringern und die Gesundheit zu erhalten.","ref":"Lektion 3.6"},{"k":"qcm","q":"Was ist eines der ersten Zeichen eines ungeeigneten Arbeitsplatzes?","a":["Verspannungen im Nacken","Plötzliche Lust, den Beruf zu wechseln","Ein Temperaturabfall im Lager","Eine Verspätung des Lieferwagens"],"ex":"Der Kurs nennt Verspannungen im Nacken.","ref":"Lektion 3.6"},{"k":"tf","q":"Ein ergonomischer Arbeitsplatz verbessert Leistung und Verfügbarkeit der Arbeitnehmenden.","v":true,"ex":"An Aufgaben und Personen anpassbare Arbeitsplätze verbessern Leistung und Verfügbarkeit.","ref":"Lektion 3.6"},{"k":"case","s":"Der Packtisch ist für Sie zu tief: Sie arbeiten den ganzen Tag gebückt.","q":"Was ist die beste Lösung?","a":["Die Höhe des Tisches auf meine Grösse einstellen","Schneller arbeiten, um weniger lang gebückt zu sein","Mich auf dem Boden hinknien","Nichts sagen: Man gewöhnt sich daran"],"ex":"Ein ergonomischer Arbeitsplatz lässt sich an die Person anpassen.","ref":"Lektion 3.6"},{"k":"match","q":"Ordnen Sie jedem Körperteil eine häufige Belastung im Lager zu.","p":[["Wirbelsäule","Mit gebeugtem Rücken heben"],["Nacken","Zu hoher oder zu tiefer Arbeitsplatz"],["Knie","Ständig in die Hocke gehen"],["Schultern","Die Arme über den Kopf heben"]],"ex":"Skelett, Gelenke und Muskeln erfahren unterschiedliche Belastungen.","ref":"Lektion 3.6 · Ergänzungen (nicht im Kursmaterial)"},{"k":"qcm","q":"Welche Art von Beschwerden verursacht eine wiederholte schlechte Haltung?","a":["Eine chronische, langsam entstehende Beschwerde","Eine akute Verletzung, die sofort auftritt","Keine Beschwerden: Der Körper passt sich an","Nur eine vorübergehende Müdigkeit am Abend"],"ex":"Gewisse Gefahren schädigen den Körper langsam und verursachen chronische Beschwerden, wie Haltungsprobleme.","ref":"Lektion 3.6"},{"k":"case","s":"Sie müssen einen schweren, sperrigen Karton verschieben, der Ihnen die Sicht verdeckt.","q":"Was tun Sie?","a":["Ich hole Hilfe oder verwende ein Hilfsmittel","Ich trage ihn allein und gehe rückwärts durch den Gang","Ich schleife ihn vornübergebeugt über den Boden","Ich hebe ihn über den Kopf, um besser zu sehen"],"ex":"Zu zweit tragen oder ein Hilfsmittel verwenden; gute Sicht behalten.","ref":"Nicht im Kursmaterial · Suva, «Heben und Tragen»"},{"k":"order","q":"Bringen Sie die Schritte zum Heben einer Last in die richtige Reihenfolge.","a":["Sich vor die Last stellen","Die Füsse schulterbreit auseinanderstellen","Die Beine beugen, Rücken gerade","Die Last nahe am Körper fassen","Sich mit den Beinen aufrichten"],"ex":"Das ist die Technik «Heben und Tragen» der Suva.","ref":"Nicht im Kursmaterial · Suva, «Heben und Tragen»"},{"k":"sort","q":"Gute oder schlechte Haltung?","c":["Gut","Schlecht"],"it":[["Rücken gerade, Beine gebeugt",0],["Oberkörper beim Tragen gedreht",1],["Last nahe am Bauch",0],["Arme weit nach vorne gestreckt",1],["Füsse auseinander, stabil",0],["Beine gestreckt, Rücken rund",1]],"ex":"Man schützt die Wirbelsäule mit geradem Rücken und der Last nahe am Körper.","ref":"Lektion 3.6 · Nicht im Kursmaterial · Suva, «Heben und Tragen»"},{"k":"odd","q":"Was verringert die Belastung des Rückens nicht?","a":["Die Last auf einer Seite tragen","Einen Scherenhubwagen verwenden","Zu zweit tragen","Die Last nahe am Körper halten"],"ex":"Auf einer Seite zu tragen bringt die Wirbelsäule aus dem Gleichgewicht.","ref":"Lektion 3.6"},{"k":"fill","q":"Um Rückenschmerzen vorzubeugen, muss man Lasten aufnehmen, ohne sich tief zu ___.","a":["bücken","heben","drehen","drücken"],"ex":"Lasten aufnehmen, ohne sich tief zu bücken.","ref":"Lektion 3.6"},{"k":"case","s":"Sie müssen regelmässig Kartons von 14 kg heben, mehr als viermal pro Stunde.","q":"Was empfiehlt die Suva in diesem Fall?","a":["Die Belastungen beurteilen lassen","Nichts: 14 kg sind immer unbedenklich","Zwei Kartons auf einmal tragen, um Zeit zu sparen","Schneller arbeiten, um früher fertig zu sein"],"ex":"Bei regelmässiger Handhabung wird eine Beurteilung ab 12 kg für Männer und 7 kg für Frauen empfohlen.","ref":"Nicht im Kursmaterial · Suva, «Heben und Tragen»"},{"k":"num","q":"Ab wie vielen Kilogramm empfiehlt die Suva, die Belastungen einer Frau zu beurteilen, die regelmässig Lasten hebt?","n":7,"tol":0,"u":"kg","ex":"7 kg für Frauen und 12 kg für Männer, bei regelmässiger Handhabung.","ref":"Nicht im Kursmaterial · Suva, «Heben und Tragen»"},{"k":"case","s":"Ihr 56-jähriger Kollege muss allein Säcke zu 25 kg tragen.","q":"Was muss man wissen?","a":["Der Richtwert sinkt mit dem Alter: Es braucht ein Hilfsmittel","Kein Problem: Seine Erfahrung gleicht das Alter mehr als aus","Er muss einfach schneller tragen, um weniger zu ermüden","Die Richtwerte betreffen nur Frauen"],"ex":"Für einen Mann über 50 Jahre liegt der Richtwert bei 16 kg.","ref":"Nicht im Kursmaterial · Suva, «Heben und Tragen»"},{"k":"tf","q":"Eine gute Hebetechnik macht Hilfsmittel überflüssig.","v":false,"ex":"Man nutzt zuerst die Hilfsmittel; die Technik schützt bei den verbleibenden Lasten.","ref":"Lektion 3.6"},{"k":"case","s":"Sie tragen eine Kiste mit gestreckten Armen weit vor sich und spüren, wie Ihr Rücken zieht.","q":"Warum muss man die Last nahe am Körper halten?","a":["Sie belastet den Rücken weniger","Sie lässt sich leichter loslassen","Sie verdeckt weniger die Sicht","Sie wird weniger beschädigt"],"ex":"Je weiter die Last vom Körper entfernt ist, desto grösser die Belastung der Wirbelsäule.","ref":"Nicht im Kursmaterial · Suva, «Heben und Tragen»"},{"k":"case","s":"Sie kommissionieren am Regal. Die schweren Artikel liegen ganz unten, direkt über dem Boden.","q":"Welche Verbesserung schlagen Sie vor?","a":["Die schweren Artikel auf Hüfthöhe lagern","Die schweren Artikel ganz oben im Regal lagern","So lassen und sich etwas schneller bücken","Diese Artikel aus dem Kommissionierlager nehmen"],"ex":"Eine Greifzone zwischen Knien und Schultern vermeidet tiefes Bücken.","ref":"Lektion 3.6 · Ergonomie"},{"k":"case","s":"Nach einer Woche intensiven Entladens haben Sie jeden Abend Schmerzen im unteren Rücken.","q":"Was ist die richtige Reaktion?","a":["Ich rede mit dem Chef und überprüfe meine Arbeitsweise","Ich mache weiter: Der Schmerz geht von selbst vorbei","Ich trage einen Gurt und hebe noch mehr","Ich verberge den Schmerz, um meine Stelle nicht zu verlieren"],"ex":"Ein wiederkehrender Schmerz ist ein Signal: Die Arbeit muss angepasst werden.","ref":"Lektion 3.6"}]},{"code":"B2.5","t":"Drucksituationen","g":"Ich beschreibe Methoden, Vorgehensweisen und Verhaltensweisen, um Drucksituationen vorzubeugen, sie zu entschärfen und zu bewältigen. (K2)","col":"coral","ic":"gauge","ch":[{"k":"qcm","q":"Was tut man zuerst, wenn man sich überfordert fühlt?","a":["Kurz innehalten und die Aufgaben priorisieren","Ohne Nachdenken Tempo machen, um alles aufzuholen","Alles liegen lassen und nach Hause gehen","Niemandem etwas sagen und allein weitermachen"],"ex":"Einen Schritt zurücktreten und Prioritäten setzen hilft, die Kontrolle zurückzugewinnen.","ref":"Nicht im Kursmaterial · Umgang mit Drucksituationen"},{"k":"case","s":"Drei Lastwagen kommen gleichzeitig an der Rampe an. Der Teamleiter ist abwesend.","q":"Welche Haltung nehmen Sie ein?","a":["Ich bleibe ruhig und setze mit dem Team Prioritäten","Ich entlade die drei Lastwagen allein gleichzeitig","Ich weise die drei Lastwagen bis morgen ab","Ich gehe in die Pause, bis der Chef zurück ist"],"ex":"Panik vorbeugen: sich absprechen, Prioritäten setzen, aufteilen.","ref":"Nicht im Kursmaterial · Umgang mit Drucksituationen"},{"k":"multi","q":"Welche Methoden helfen, Drucksituationen vorzubeugen?","good":["Seinen Tag planen","Prioritäten setzen","Ein Problem früh melden","Regelmässig Pausen machen"],"bad":["Alle Probleme für sich behalten","Jeden Tag die Pausen auslassen"],"ex":"Planung, Prioritäten, Kommunikation und Erholung.","ref":"Nicht im Kursmaterial · Umgang mit Drucksituationen"},{"k":"tf","q":"Unter Druck lässt man besser die Kontrollen aus, um Zeit zu sparen.","v":false,"ex":"Druck erhöht das Fehler- und Unfallrisiko: Die Kontrollen bleiben unerlässlich.","ref":"Nicht im Kursmaterial · Umgang mit Drucksituationen · Lektion 3.6"},{"k":"case","s":"Ein Kunde schreit am Telefon, weil seine Lieferung Verspätung hat.","q":"Wie entschärfen Sie die Situation?","a":["Ich bleibe ruhig, höre zu und schlage eine Lösung vor","Ich werde laut, um mir endlich Gehör zu verschaffen","Ich hänge wortlos auf, um es kurz zu machen","Ich sage ihm, dass das wirklich nicht mein Problem ist"],"ex":"Ruhe, Zuhören und eine konkrete Lösung entschärfen den Konflikt.","ref":"Nicht im Kursmaterial · Umgang mit Drucksituationen"},{"k":"order","q":"Bringen Sie den Umgang mit einer Drucksituation in die richtige Reihenfolge.","a":["Den Druck erkennen","Durchatmen und Abstand gewinnen","Prioritäten setzen","Wenn nötig um Hilfe bitten","Danach Bilanz ziehen"],"ex":"Erkennen, sich beruhigen, organisieren, sich gegenseitig helfen, dann Lehren ziehen.","ref":"Nicht im Kursmaterial · Umgang mit Drucksituationen"},{"k":"qcm","q":"Warum erhöht Druck das Unfallrisiko?","a":["Man eilt und vernachlässigt die Regeln","Man wird im Gegenteil viel vorsichtiger","Man trägt mehr PSA als sonst üblich","Man arbeitet langsamer und sorgfältiger"],"ex":"80 % der Unfälle entstehen durch gefährliches Verhalten wie Nachlässigkeit oder Risikobereitschaft.","ref":"Lektion 3.6 · Nicht im Kursmaterial · Umgang mit Drucksituationen"},{"k":"case","s":"Ihr Chef verlangt eine dringende Aufgabe, obwohl Sie schon drei laufende haben.","q":"Was tun Sie?","a":["Ich frage ihn, welche Vorrang hat","Ich nehme alles wortlos an","Ich lehne die neue Aufgabe schroff ab","Ich erledige die vier Aufgaben halb"],"ex":"Prioritäten zu klären vermeidet Überlastung und Fehler.","ref":"Nicht im Kursmaterial · Umgang mit Drucksituationen"},{"k":"match","q":"Ordnen Sie jeder Methode ihre Wirkung zu.","p":[["Planen","Arbeitsspitzen vorwegnehmen"],["Priorisieren","Zuerst das Wesentliche tun"],["Kommunizieren","Böse Überraschungen vermeiden"],["Sich erholen","Seine Energie bewahren"]],"ex":"Jede Methode wirkt auf eine Ursache von Druck.","ref":"Nicht im Kursmaterial · Umgang mit Drucksituationen"},{"k":"sort","q":"Hilft dieses Verhalten, mit Druck umzugehen?","c":["Hilft","Verschlimmert"],"it":[["Ruhig atmen",0],["Einen Kollegen anschreien",1],["Um Hilfe bitten",0],["Das Problem für sich behalten",1],["Eine Prioritätenliste erstellen",0],["Die Pause streichen",1]],"ex":"Ruhe, gegenseitige Hilfe und Organisation helfen; Isolation und Erschöpfung verschlimmern.","ref":"Nicht im Kursmaterial · Umgang mit Drucksituationen"},{"k":"case","s":"Ein Kollege ist sehr gestresst und beginnt, den Stapler zu schnell zu fahren.","q":"Was tun Sie?","a":["Ich spreche ihn ruhig an und biete ihm Hilfe an","Ich lasse ihn machen, das geht mich nichts an","Ich mache mich vor dem Team über ihn lustig","Ich fahre noch schneller, um ihm zu helfen"],"ex":"Entschärfen heisst auch, einem Kollegen vor dem Unfall zu helfen.","ref":"Nicht im Kursmaterial · Umgang mit Drucksituationen"},{"k":"odd","q":"Was ist keine Methode, um Druck vorzubeugen?","a":["Alles auf den letzten Moment verschieben","Seine Woche planen","Eine Verspätung früh melden","Sein Material im Voraus bereitstellen"],"ex":"Alles aufzuschieben erzeugt gerade den Druck.","ref":"Nicht im Kursmaterial · Umgang mit Drucksituationen"},{"k":"tf","q":"Eine kurze Pause kann helfen, eine Drucksituation besser zu bewältigen.","v":true,"ex":"Erholung hilft, konzentriert zu bleiben und weniger Fehler zu machen.","ref":"Nicht im Kursmaterial · Umgang mit Drucksituationen"},{"k":"case","s":"Es ist 16.30 Uhr. Es bleiben 20 Aufträge, die Abholung ist um 17 Uhr, und Sie wissen, dass Sie nicht fertig werden.","q":"Was tun Sie?","a":["Ich informiere sofort meinen Vorgesetzten","Ich mache weiter und hoffe, dass es reicht","Ich pfusche bei den Kontrollen, um alles zu schaffen","Ich verschicke die Aufträge unvollständig"],"ex":"Früh zu kommunizieren erlaubt, eine Lösung zu finden (Verstärkung, Priorität, Verschiebung).","ref":"Nicht im Kursmaterial · Umgang mit Drucksituationen"},{"k":"fill","q":"Um einen Konflikt zu entschärfen, muss man zuerst ___ bleiben.","a":["ruhig","stumm","fern","eilig"],"ex":"Ruhe verhindert, dass die Spannung steigt.","ref":"Nicht im Kursmaterial · Umgang mit Drucksituationen"},{"k":"qcm","q":"Was ermöglicht eine gute Planung?","a":["Arbeitsreiche Zeiten vorwegzunehmen","Alle Zwischenfälle zu beseitigen","Ganz ohne Pause zu arbeiten","Ganz ohne das Team auszukommen"],"ex":"Sie beseitigt keine Zwischenfälle, hilft aber, sie besser aufzufangen.","ref":"Nicht im Kursmaterial · Umgang mit Drucksituationen"},{"k":"case","s":"Während der Jahresendinventur reihen Sie Stunde an Stunde und schlafen schlecht.","q":"Was tun Sie?","a":["Ich melde es und achte darauf, mich in den Pausen zu erholen","Ich trinke den ganzen Tag Energydrinks","Ich verberge meine Müdigkeit vor dem Teamleiter, um nicht zu stören","Ich mache noch mehr Stunden, um schnell fertig zu werden"],"ex":"Müdigkeit erhöht Fehler und Unfälle: Man muss sich erholen.","ref":"Nicht im Kursmaterial · Umgang mit Drucksituationen"},{"k":"multi","q":"Welche Zeichen zeigen, dass man unter zu starkem Druck steht?","good":["Reizbarkeit","Ungewohnte Fehler","Schlafstörungen","Muskelverspannungen"],"bad":["Gute Konzentration","Anhaltende Ruhe"],"ex":"Wer diese Zeichen erkennt, kann früh handeln.","ref":"Nicht im Kursmaterial · Umgang mit Drucksituationen · Lektion 3.6"},{"k":"case","s":"Ein eiliger Chauffeur bittet Sie, seinen Anhänger ohne Kontrolle der Pakete zu beladen.","q":"Was antworten Sie?","a":["Ich mache die Kontrolle und sage ihm, wie lange es dauert","Ich lade ohne Kontrolle, um ihm einen Gefallen zu tun","Ich weigere mich, ihn zu bedienen, und schicke ihn ins Büro","Ich sage ihm, er solle seinen Anhänger selbst beladen"],"ex":"Der Druck anderer rechtfertigt nicht, ein Vorgehen auszulassen.","ref":"Nicht im Kursmaterial · Umgang mit Drucksituationen"},{"k":"qcm","q":"Was muss man nach einer Situation mit starkem Druck tun?","a":["Bilanz ziehen, um sich nächstes Mal besser zu organisieren","Schnell vergessen und nie mehr mit dem Team darüber reden","Unter den anwesenden Kollegen einen Schuldigen suchen","So bald wie möglich die Firma wechseln"],"ex":"Lehren ziehen hilft, beim nächsten Mal vorzubeugen.","ref":"Nicht im Kursmaterial · Umgang mit Drucksituationen"},{"k":"tf","q":"Um Hilfe zu bitten, wenn man überfordert ist, ist ein Zeichen von Schwäche.","v":false,"ex":"Es ist im Gegenteil ein guter beruflicher Reflex.","ref":"Nicht im Kursmaterial · Umgang mit Drucksituationen"},{"k":"case","s":"Ihr Teamleiter wirft Ihnen vor allen in scharfem Ton einen Fehler vor.","q":"Wie reagieren Sie?","a":["Ich bleibe ruhig und bitte um ein Gespräch allein","Ich antworte ihm vor dem Team im selben Ton","Ich verlasse wortlos meinen Posten","Ich schiebe die Schuld auf einen abwesenden Kollegen"],"ex":"Ruhig bleiben und den richtigen Moment für ein Gespräch wählen entschärft den Konflikt.","ref":"Nicht im Kursmaterial · Umgang mit Drucksituationen"},{"k":"case","s":"Sie rüsten einen dringenden Auftrag und Ihr Telefon klingelt dauernd wegen Nebensächlichkeiten.","q":"Was tun Sie?","a":["Ich beende den dringenden Auftrag und rufe dann zurück","Ich beantworte jeden Anruf beim Rüsten","Ich schalte mein Telefon für den Tag aus","Ich lasse den Auftrag liegen, um alles zu beantworten"],"ex":"Priorisieren: zuerst das Dringende, dann der Rest.","ref":"Nicht im Kursmaterial · Umgang mit Drucksituationen"},{"k":"qcm","q":"Was ist ein unter Druck nützliches «Vorgehen»?","a":["Ein im Voraus bekannter Ablauf","Eine Improvisation in letzter Minute","Eine Regel, die man in Eile vergisst","Ein geschriener Befehl"],"ex":"Ein klares Vorgehen erspart das Nachdenken in der Hektik und verringert Fehler.","ref":"Nicht im Kursmaterial · Umgang mit Drucksituationen"},{"k":"case","s":"Der Montagmorgen ist im Lager immer chaotisch: viele Aufträge und schlecht versorgtes Material.","q":"Welche vorbeugende Massnahme schlagen Sie vor?","a":["Rampe und Material freitags vorbereiten","Am Montagmorgen einfach später kommen","Nichts ändern: Es ist immer so","Alle Aufträge vom Montag ablehnen"],"ex":"Vorausplanen beugt Druck vor.","ref":"Nicht im Kursmaterial · Umgang mit Drucksituationen"}]},{"code":"B3.8","t":"Risiken und Gefahren","g":"Ich beschreibe anhand von Beispielen die Risiken und Gefahren, die im logistischen Prozess für mich, für die Mitarbeitenden und für Dritte auftreten. (K2)","col":"amber","ic":"warning","ch":[{"k":"num","q":"Wie viel Prozent der Unfälle sind laut Kurs auf gefährliches Verhalten zurückzuführen?","n":80,"tol":0,"u":"%","ex":"80 % der Unfälle sind auf gefährliches Verhalten zurückzuführen, 20 % auf gefährliche Zustände.","ref":"Lektion 3.6"},{"k":"num","q":"Wie viel Prozent der Unfälle sind auf gefährliche Zustände zurückzuführen?","n":20,"tol":0,"u":"%","ex":"20 %: fehlende Schutzeinrichtungen, Konstruktionsmängel.","ref":"Lektion 3.6"},{"k":"multi","q":"Welche gefährlichen Verhaltensweisen nennt der Kurs?","good":["Missachtung der Regeln","Nachlässigkeit","Nichtanwenden der Schutzmassnahmen","Bewusstes Eingehen von Risiken"],"bad":["Tragen der PSA","Melden eines Mangels"],"ex":"Das sind die vier gefährlichen Verhaltensweisen des Kurses.","ref":"Lektion 3.6"},{"k":"sort","q":"Gefährliches Verhalten oder gefährlicher Zustand?","c":["Verhalten","Zustand"],"it":[["Mit dem Stapler zu schnell fahren",0],["Fehlendes Geländer an der Rampe",1],["Die Handschuhe nicht tragen",0],["Schlecht an der Wand befestigtes Regal",1],["Auf eine Palette steigen, um einen Karton zu erreichen",0],["Defekte Beleuchtung im Gang",1]],"ex":"Verhalten = was die Person tut; Zustand = Beschaffenheit von Ort oder Material.","ref":"Lektion 3.6"},{"k":"qcm","q":"Was ist eine akute Gefahr?","a":["Eine Gefahr, die kurzfristig eine Verletzung verursacht","Eine Gefahr, die den Körper über Jahre abnutzt","Eine Gefahr, die nie eine Folge hat","Eine Gefahr, die nur die Maschinen im Lager betrifft"],"ex":"Akute Gefahren treten kurzfristig auf; andere schädigen den Körper langsam.","ref":"Lektion 3.6"},{"k":"match","q":"Ordnen Sie jeder Gefahr ihre Art der Wirkung zu.","p":[["Fuss von einem Rad gequetscht","Akut"],["Wiederholte schlechte Haltung","Chronisch"],["Schnitt durch ein Umreifungsband","Akut"],["Ständiger Lärm am Arbeitsplatz","Chronisch"]],"ex":"Akut: sofort. Chronisch: stellt sich langsam ein.","ref":"Lektion 3.6"},{"k":"multi","q":"Welche Unfälle können Gefahren laut Kurs verursachen?","good":["Schnittverletzungen","Knochenbrüche","Quetschungen","Innere Verletzungen"],"bad":["Sonnenbrand im Büro","Tippfehler"],"ex":"Der Kurs nennt Schnitte, Brüche, Quetschungen und innere Verletzungen.","ref":"Lektion 3.6"},{"k":"case","s":"Ein Besucher durchquert das Lager ohne Weste, mitten zwischen den Gabelstaplern.","q":"Wer ist in Gefahr und was tun Sie?","a":["Der Besucher: Ich begleite ihn hinaus","Niemand: Er kennt die Räume sicher sehr gut","Nur die Staplerfahrer: Ich tue also gar nichts","Der Besucher, aber nur er selbst muss aufpassen"],"ex":"Die Gefahren des logistischen Prozesses betreffen auch Dritte.","ref":"Lektion 3.6 · Dritte"},{"k":"case","s":"Ein Kollege steigt auf die Gabeln des Gabelstaplers, um einen hoch gelagerten Karton zu erreichen.","q":"Um welche Art von Unfallursache handelt es sich?","a":["Ein bewusst eingegangenes Risiko","Ein gefährlicher Zustand des Staplers","Ein Konstruktionsmangel des Geräts","Ein ganz einfach unvermeidbarer Unfall"],"ex":"Das ist gefährliches Verhalten: bewusstes Risiko und Missachtung der Regeln.","ref":"Lektion 3.6"},{"k":"case","s":"Sie beladen einen Lastwagen. Der Chauffeur steht hinter dem Anhänger, während Sie mit dem Stapler rückwärts fahren.","q":"Welches Risiko besteht?","a":["Den Chauffeur als Drittperson zu überfahren","Nur den Anhänger des Lastwagens zu beschädigen","Keines: Der Chauffeur kennt seinen Lastwagen gut","Die Pakete am Rand der Rampe zu verschmutzen"],"ex":"Dritte (Chauffeure, Besucher) sind den Gefahren an der Rampe ausgesetzt.","ref":"Lektion 3.6"},{"k":"tf","q":"In der Logistik sind gewisse Gefahren typisch für den Beruf.","v":true,"ex":"Manipulation, Fahrzeugverkehr, herabfallende Gegenstände.","ref":"Lektion 3.6"},{"k":"qcm","q":"Welche Gefahren sind typisch für die Logistik?","a":["Manipulation, Verkehr, fallende Gegenstände","Ertrinken, Lawinen und Blitzschlag im Lager","Küchenverbrennungen und Messerschnitte am Herd","Keine: Logistik ist ein Beruf ohne Risiko"],"ex":"Der Kurs nennt diese drei typischen Gefahrenquellen.","ref":"Lektion 3.6"},{"k":"case","s":"Eine schlecht umwickelte Palette ist hoch im Regal über dem Gang gelagert.","q":"Für wen ist das gefährlich?","a":["Für jede Person, die durch den Gang geht","Nur für die Person, die sie eingelagert hat","Für niemanden, solange sie nicht fällt","Nur für die Ware"],"ex":"Herabfallende Gegenstände bedrohen einen selbst, die Kollegen und Dritte.","ref":"Lektion 3.6"},{"k":"order","q":"Bringen Sie die Reaktion auf eine erkannte Gefahr in die richtige Reihenfolge.","a":["Die Gefahr erkennen","Sich und andere schützen","Die Zone sichern","Der verantwortlichen Person melden","Prüfen, ob die Gefahr beseitigt ist"],"ex":"Man lässt eine Gefahr nie unbehandelt.","ref":"Lektion 3.6 · Vorgehen (nicht im Kursmaterial)"},{"k":"odd","q":"Was ist kein gefährliches Verhalten?","a":["Ein beschädigtes Regal melden","Eine Anweisung ignorieren","Fahren, ohne zu schauen","Die PSA nicht tragen"],"ex":"Einen Mangel zu melden ist im Gegenteil ein guter Reflex.","ref":"Lektion 3.6"},{"k":"fill","q":"80 % der Unfälle gehen auf ein ___ Verhalten zurück.","a":["gefährliches","vorsichtiges","unvorhersehbares","technisches"],"ex":"Nur 20 % gehen auf gefährliche Zustände zurück.","ref":"Lektion 3.6"},{"k":"case","s":"Sie bemerken, dass das Geländer der Verladerampe kaputt ist.","q":"Was tun Sie?","a":["Ich sichere die Zone und melde den Mangel","Ich passe auf und rede nicht darüber","Ich warte, bis jemand stürzt, und melde es dann","Ich repariere es selbst mit Stretchfolie"],"ex":"Das ist ein gefährlicher Zustand: Er muss gemeldet und behoben werden.","ref":"Lektion 3.6"},{"k":"qcm","q":"Warum zählt das Verhalten in der Prävention so viel?","a":["Es ist die Ursache der meisten Unfälle","Es zählt nicht: Nur die Maschinen zählen","Es betrifft nur neue Mitarbeitende","Es betrifft nur den Teamleiter"],"ex":"80 % der Unfälle entstehen durch gefährliches Verhalten.","ref":"Lektion 3.6"},{"k":"tf","q":"Gefahren gibt es nur bei der Arbeit.","v":false,"ex":"Sie sind allgegenwärtig: zu Hause, in der Natur, im Verkehr und bei der Arbeit.","ref":"Lektion 3.6"},{"k":"case","s":"Ein Lernender hört beim Fahren eines elektrischen Handhubwagens mit Kopfhörern Musik.","q":"Welches Risiko schafft er?","a":["Er hört keine Warnungen mehr und kann jemanden verletzen","Keines: Die Musik hilft ihm, sich besser zu konzentrieren","Er riskiert nur, seine Kopfhörer im Gang zu verlieren","Er schafft nur ein Risiko für den Handhubwagen selbst"],"ex":"Nachlässigkeit und Missachtung der Regeln: eine Gefahr für ihn und für andere.","ref":"Lektion 3.6"},{"k":"case","s":"Beim Entladen fällt ein Karton von einer instabilen Palette und streift beinahe einen Kollegen.","q":"Was tun Sie danach?","a":["Ich stabilisiere die Palette und melde den Vorfall","Ich hebe den Karton auf und arbeite weiter","Ich lache: Niemand wurde getroffen, alles gut","Ich verstecke den beschädigten Karton hinter einer Palette"],"ex":"Ein «Beinaheunfall» muss gemeldet werden, um den nächsten Unfall zu verhindern.","ref":"Lektion 3.6"},{"k":"qcm","q":"Was sind «gefährliche Zustände»?","a":["Ein Mangel an Ort oder Material","Ein Fehlverhalten","Ein unzufriedener Kunde am Telefon","Angenehmes Wetter an der Rampe"],"ex":"Zum Beispiel fehlende Schutzeinrichtungen oder Konstruktionsmängel.","ref":"Lektion 3.6"},{"k":"case","s":"Ein Kollege legt auf dem Gabelstapler den Sicherheitsgurt nicht an, «um schneller abzusteigen».","q":"Um welches gefährliche Verhalten handelt es sich?","a":["Das Nichtanwenden einer Schutzmassnahme","Ein gefährlicher Zustand des Staplers","Ein Konstruktionsmangel des Geräts","Ein Verhalten ohne echtes Risiko"],"ex":"Eine Schutzmassnahme nicht anzuwenden ist gefährliches Verhalten.","ref":"Lektion 3.6"},{"k":"case","s":"Ein externer Lieferant parkiert seinen Lieferwagen vor einem Notausgang des Lagers.","q":"Für wen ist das gefährlich?","a":["Für alle bei einer Evakuierung","Für niemanden: Es ist nur vorübergehend","Nur für den Lieferanten, der ihn dort parkiert hat","Nur für den Lieferwagen selbst"],"ex":"Ein blockierter Durchgang gefährdet Mitarbeitende und Dritte.","ref":"Lektion 3.6 · Dritte"},{"k":"qcm","q":"Welche Wirkung hat eine chronische Gefahr?","a":["Sie schädigt den Körper langsam","Sie verursacht sofort einen Bruch","Sie verschwindet über Nacht","Sie betrifft nur die Geräte"],"ex":"Sie verursacht chronische Beschwerden oder Krankheiten, wie Haltungsprobleme.","ref":"Lektion 3.6"}]},{"code":"B3.9","t":"Notfallorganisation","g":"Ich nenne die wichtigsten Elemente einer Notfallorganisation und erkläre die Abläufe, das Verhalten und die Massnahmen gemäss dem Notfallplan des Unternehmens. (K2)","col":"emerald","ic":"siren","ch":[{"k":"qcm","q":"Welche Nummer rufen Sie in der Schweiz für eine Ambulanz an?","a":["144","117","118","145"],"ex":"144: Sanität. 117: Polizei. 118: Feuerwehr. 145: Tox Info.","ref":"Nicht im Kursmaterial · Suva, Verhalten im Notfall"},{"k":"match","q":"Ordnen Sie jeder Notrufnummer ihren Dienst zu.","p":[["144","Sanität"],["118","Feuerwehr"],["117","Polizei"],["145","Tox Info Suisse"]],"ex":"Das sind die Schweizer Notrufnummern.","ref":"Nicht im Kursmaterial · Suva, Verhalten im Notfall"},{"k":"num","q":"Wie lautet die Nummer der Rega (Luftrettung)?","n":1414,"tol":0,"u":"","ex":"Die Rega erreicht man unter 1414.","ref":"Nicht im Kursmaterial · Suva, Verhalten im Notfall"},{"k":"num","q":"Wie lautet die europäische Notrufnummer, die auch in der Schweiz gilt?","n":112,"tol":0,"u":"","ex":"Die 112 funktioniert in ganz Europa, auch mit einer ausländischen SIM-Karte.","ref":"Nicht im Kursmaterial · Suva, Verhalten im Notfall"},{"k":"case","s":"Ein Kollege bekommt Batteriesäure in die Augen.","q":"Was tun Sie sofort?","a":["Ich bringe ihn zur Augendusche und lasse den Notruf alarmieren","Ich sage ihm, er solle sich die Augen mit den Händen reiben","Ich warte mit ihm, bis der Schmerz von selbst vergeht","Ich leihe ihm meine Sonnenbrille zum Schutz der Augen"],"ex":"Augendusche mit Salzlösung, dann notfallmässig zum Augenarzt.","ref":"Lektion 3.6"},{"k":"qcm","q":"Was muss man nach dem Gebrauch der Augendusche tun?","a":["Notfallmässig zum Augenarzt","Sofort normal weiterarbeiten","Bis am nächsten Morgen warten","Augentropfen aus dem Handel geben"],"ex":"Der Kurs verlangt, notfallmässig einen Augenarzt aufzusuchen.","ref":"Lektion 3.6"},{"k":"tf","q":"Man muss wissen, wo die Augendusche ist, bevor man sie braucht.","v":true,"ex":"Im Notfall zählt jede Sekunde.","ref":"Lektion 3.6"},{"k":"order","q":"Bringen Sie die Verhaltensregel im Notfall in die richtige Reihenfolge.","a":["Schauen und die Lage beurteilen","Über die Gefahren für sich und andere nachdenken","Handeln: alarmieren, dann helfen"],"ex":"Die Suva fasst das Verhalten im Notfall zusammen: schauen, denken, handeln.","ref":"Nicht im Kursmaterial · Suva, Verhalten im Notfall"},{"k":"multi","q":"Welche Elemente gehören zu einer Notfallorganisation?","good":["Notfall- und Evakuationsplan","Ausgehängte Notrufnummern","Ausgebildete Ersthelfer","Sammelplatz"],"bad":["Ferienplan","Preisliste"],"ex":"Plan, Alarm, Nummern, Ersthelfer, Erste-Hilfe-Material und Sammelplatz.","ref":"Nicht im Kursmaterial · Suva, Verhalten im Notfall"},{"k":"case","s":"Der Feueralarm ertönt, während Sie einen Auftrag rüsten.","q":"Was tun Sie?","a":["Ich höre auf zu arbeiten und gehe zum Sammelplatz","Ich beende meinen Auftrag und schaue dann, was los ist","Ich nehme den Lift, um so schnell wie möglich hinauszukommen","Ich suche zuerst, woher das Feuer kommt, um es zu löschen"],"ex":"Man befolgt den Evakuationsplan: Man verlässt das Gebäude über die Ausgänge, ohne Lift.","ref":"Nicht im Kursmaterial · Suva, Verhalten im Notfall"},{"k":"qcm","q":"Warum geht man zum Sammelplatz?","a":["Damit man die evakuierten Personen zählen kann","Um in Ruhe das Ende des Tages abzuwarten","Um mit Kollegen über die Ursache des Alarms zu reden","Um die in der Garderobe gebliebenen Sachen zu holen"],"ex":"So prüft man, dass niemand fehlt.","ref":"Nicht im Kursmaterial · Suva, Verhalten im Notfall"},{"k":"case","s":"Ein Kollege ist unter einer umgestürzten Palette am Bein verletzt. Er ist bei Bewusstsein.","q":"Was ist das Erste, was zu tun ist?","a":["Die Zone sichern, um mich nicht selbst zu gefährden","Die Palette allein mit blossen Händen sehr schnell anheben","Ihn an den Armen aus der Arbeitszone ziehen","Die Szene für den Unfallbericht filmen"],"ex":"Sich zuerst schützen, dann alarmieren (144) und helfen.","ref":"Nicht im Kursmaterial · Suva, Verhalten im Notfall"},{"k":"multi","q":"Welche Angaben macht man bei einem Anruf an die 144?","good":["Wer anruft","Wo sich die verletzte Person befindet","Was passiert ist","Wie viele Verletzte"],"bad":["Der Preis der Ware","Der Name des belieferten Kunden"],"ex":"Wer, wo, was, wie viele: Diese Angaben erlauben, die richtige Hilfe zu schicken.","ref":"Nicht im Kursmaterial · Suva, Verhalten im Notfall"},{"k":"sort","q":"Welche Nummer anrufen?","c":["144","118","145"],"it":[["Ein Kollege bricht zusammen",0],["Im Batterieraum bricht ein Feuer aus",1],["Ein Kollege hat ein Reinigungsmittel geschluckt",2],["Ein Staplerfahrer ist verletzt und blutet",0],["Aus einem Container steigt Rauch",1],["Giftige Dämpfe nach dem Mischen von Produkten",2]],"ex":"144: medizinischer Notfall. 118: Feuer. 145: Vergiftung.","ref":"Nicht im Kursmaterial · Suva, Verhalten im Notfall"},{"k":"odd","q":"Was gehört nicht zum Verhalten bei einer Evakuierung?","a":["Den Lift nehmen","Den Notausgängen folgen","Personen in Schwierigkeiten helfen","Zum Sammelplatz gehen"],"ex":"Bei einem Brand benutzt man nie den Lift.","ref":"Nicht im Kursmaterial · Suva, Verhalten im Notfall"},{"k":"fill","q":"Im Notfall muss man zuerst auf die eigene ___ achten.","a":["Sicherheit","Kleidung","Reputation","Position"],"ex":"Sich nicht selbst in Gefahr bringen.","ref":"Nicht im Kursmaterial · Suva, Verhalten im Notfall"},{"k":"case","s":"Sie sind neu im Lager. Niemand hat Ihnen den Notfallplan gezeigt.","q":"Was tun Sie?","a":["Ich frage, wo Plan, Ausgänge und Sammelplatz sind","Ich warte auf einen echten Alarm, um zu sehen, was passiert","Ich folge immer den Kollegen, das genügt","Nichts: Das ist in der Logistik nicht wirklich nützlich"],"ex":"Alle müssen den Notfallplan des Unternehmens kennen.","ref":"Nicht im Kursmaterial · Suva, Verhalten im Notfall"},{"k":"tf","q":"Ein Notausgang darf mit Paletten verstellt werden, wenn es nur vorübergehend ist.","v":false,"ex":"Notausgänge bleiben immer frei.","ref":"Nicht im Kursmaterial · Suva, Verhalten im Notfall"},{"k":"case","s":"Ihr Unternehmen zieht in ein neues Lager. Sie wollen wissen, wie Sie bei einem Brand reagieren müssen.","q":"Wo finden Sie die Abläufe für einen Notfall?","a":["Im Notfallplan des Unternehmens","Im Produktkatalog","Im Lieferschein des Tages","Im mit dem Kunden unterzeichneten Vertrag"],"ex":"Der Notfallplan beschreibt Abläufe, Verhalten und Massnahmen.","ref":"Nicht im Kursmaterial · Suva, Verhalten im Notfall"},{"k":"case","s":"Aus einem Fass läuft eine unbekannte Flüssigkeit mit starkem Geruch.","q":"Was tun Sie?","a":["Ich entferne mich, alarmiere und wende den Notfallplan an","Ich wische die Flüssigkeit mit einem Lappen auf","Ich rieche aus der Nähe daran, um das Produkt zu erkennen","Ich arbeite etwas weiter weg vom Fass weiter"],"ex":"Sich schützen, alarmieren, das Vorgehen anwenden.","ref":"Nicht im Kursmaterial · Suva, Verhalten im Notfall"},{"k":"qcm","q":"Was enthält eine fest installierte Augendusche?","a":["Eine Salzlösung oder sauberes Wasser","Ein Desinfektionsmittel auf Alkoholbasis","Ein Reinigungsmittel für Brillen","Eine beruhigende Hautcrème"],"ex":"Der Kurs spricht von einer Augendusche mit Salzlösung.","ref":"Lektion 3.6"},{"k":"case","s":"Bei einer Evakuationsübung will ein Kollege an seinem Platz bleiben, «um keine Zeit zu verlieren».","q":"Was sagen Sie ihm?","a":["Dass die Übung Pflicht ist und hilft, richtig zu reagieren","Dass er recht hat: Es ist nur eine einfache Übung","Dass er bleiben darf, wenn er die Tür schliesst","Dass der Chef an seiner Stelle entscheiden muss"],"ex":"Übungen sorgen für die richtigen Reflexe am Tag eines echten Alarms.","ref":"Nicht im Kursmaterial · Suva, Verhalten im Notfall"},{"k":"tf","q":"Die 112 kann in der Schweiz bei jedem Notfall angerufen werden.","v":true,"ex":"Sie verbindet mit einer Alarmzentrale, die an die richtigen Rettungsdienste weiterleitet.","ref":"Nicht im Kursmaterial · Suva, Verhalten im Notfall"},{"k":"case","s":"Ein Kollege hat sich mit einem Cutter tief in die Hand geschnitten. Es blutet stark.","q":"Was tun Sie zuerst?","a":["Ich drücke auf die Wunde und lasse die 144 anrufen","Ich sage ihm, er solle allein auf der Toilette ausspülen","Ich klebe ein Pflaster drauf und er arbeitet weiter","Ich warte auf den Ersthelfer, ohne etwas anderes zu tun"],"ex":"Auf die Wunde drücken und den Notruf alarmieren.","ref":"Nicht im Kursmaterial · Suva, Verhalten im Notfall"},{"k":"qcm","q":"Wer muss die Notfallorganisation kennen?","a":["Alle Mitarbeitenden","Nur der Firmenchef","Nur die Ersthelfer","Nur die Feuerwehr"],"ex":"Alle müssen wissen, wie sie reagieren müssen.","ref":"Nicht im Kursmaterial · Suva, Verhalten im Notfall"}]},{"code":"C1.3","t":"Förder- und Hebegeräte","g":"Ich beschreibe die Förder- und Hebegeräte (Gabelstapler, Brückenkran, Hebebalken, Scherenhubtisch, Hebe- und Transporthilfen, Exoskelette), ihre Merkmale und ihre Einsatzbereiche im Wareneingang. (K2)","col":"sky","ic":"forklift","ch":[{"k":"match","q":"Ordnen Sie jedem Gerät seinen Einsatz zu.","p":[["Gabelstapler","Paletten in die Höhe heben und stapeln"],["Brückenkran","Schwere hängende Lasten bewegen"],["Scherenhubtisch","Eine Last auf gute Arbeitshöhe bringen"],["Exoskelett","Rücken oder Schultern entlasten"]],"ex":"Jedes Gerät hat seine Merkmale und seinen Einsatzbereich.","ref":"Nicht im Kursmaterial · Förder- und Hebegeräte"},{"k":"qcm","q":"Was ist ein Hebebalken (Traverse)?","a":["Ein Hebezubehör, das die Last auf mehrere Punkte verteilt","Ein zweirädriger Wagen zum Verschieben gestapelter Pakete","Ein Tisch, der auf Arbeitshöhe hoch- und runterfährt","Ein Rollenförderband vom Wareneingang zum Lager"],"ex":"Der Hebebalken hängt an einem Kran oder Brückenkran und verteilt die Last.","ref":"Nicht im Kursmaterial · Förder- und Hebegeräte"},{"k":"qcm","q":"Was ist ein Exoskelett?","a":["Eine getragene Stütze für einen Körperteil","Ein autonomer Wagen, der ohne Fahrer fährt","Ein auf Bodenschienen montiertes Fahrregal","Eine leichte Palette aus rezykliertem Kunststoff"],"ex":"Es ist eine von der Person getragene äussere Struktur, die zum Beispiel Rücken oder Schultern unterstützt.","ref":"Nicht im Kursmaterial · SECO, «Exoskelette»"},{"k":"tf","q":"Ein Exoskelett ersetzt technische und organisatorische Massnahmen.","v":false,"ex":"Es ist eine Ergänzung: Das STOP-Prinzip bleibt die Regel.","ref":"Nicht im Kursmaterial · SECO, «Exoskelette»"},{"k":"case","s":"Sie nehmen einen Lastwagen mit Getränkepaletten entgegen, die auf drei Ebenen gestapelt werden sollen.","q":"Welches Gerät passt?","a":["Der Gabelstapler","Der Scherenhubtisch","Die Sackkarre","Das Exoskelett"],"ex":"Der Gabelstapler hebt und stapelt Paletten in die Höhe.","ref":"Nicht im Kursmaterial · Förder- und Hebegeräte"},{"k":"case","s":"Im Wareneingang muss ein Metallteil von 800 kg aus einer oben offenen Kiste gehoben werden.","q":"Welches Mittel passt?","a":["Ein Brückenkran mit Hebebalken","Zwei Kollegen, die es mit blossen Händen heben","Eine Sackkarre, um es zu kippen und zu rollen","Einen Handhubwagen unter die Kiste schieben"],"ex":"Der Brückenkran hebt schwere hängende Lasten.","ref":"Nicht im Kursmaterial · Förder- und Hebegeräte"},{"k":"case","s":"Sie müssen den ganzen Morgen die Kartons einer am Boden stehenden Palette von Hand auspacken.","q":"Welches Mittel verringert die Belastung Ihres Rückens?","a":["Einen Scherenhubtisch","Einen Brückenkran mit Hebebalken","Einen Hochhubwagen mit Fahrerstand","Einen Hängeförderer mit Haken"],"ex":"Der Scherenhubtisch bringt die Last auf gute Höhe und vermeidet Bücken.","ref":"Lektion 3.6 · Nicht im Kursmaterial · Förder- und Hebegeräte"},{"k":"sort","q":"Hebegerät oder Transporthilfe?","c":["Heben","Transport am Boden"],"it":[["Brückenkran",0],["Sackkarre",1],["Hubtisch",0],["Handhubwagen",1],["Elektrischer Kettenzug",0],["Plattformwagen",1]],"ex":"Das Hebegerät hebt die Last; die Transporthilfe bewegt sie am Boden.","ref":"Nicht im Kursmaterial · Förder- und Hebegeräte"},{"k":"multi","q":"Welche Bedingungen muss man erfüllen, um einen Gabelstapler zu fahren?","good":["Die Staplerfahrer-Ausbildung absolviert haben","Vom Arbeitgeber dazu ermächtigt sein","Das Gerät vor dem Gebrauch kontrollieren"],"bad":["Nur den Autoführerausweis haben","Einen Kollegen dabei beobachtet haben"],"ex":"Das Fahren von Gabelstaplern verlangt eine Ausbildung und eine Bewilligung.","ref":"Nicht im Kursmaterial · Förder- und Hebegeräte"},{"k":"qcm","q":"Was ist das Hauptrisiko unter einem belasteten Brückenkran?","a":["Der Absturz der hängenden Last","Der Lärm des Elektromotors","Die Kälte in der Halle des Wareneingangs","Der am Boden aufgewirbelte Staub"],"ex":"Man geht nie unter einer hängenden Last durch.","ref":"Nicht im Kursmaterial · Förder- und Hebegeräte"},{"k":"tf","q":"Man darf unter einer hängenden Last durchgehen, wenn man einen Helm trägt.","v":false,"ex":"Der Helm schützt nicht vor dem Absturz einer schweren Last: Man geht nie darunter durch.","ref":"Lektion 3.6 · Nicht im Kursmaterial · Förder- und Hebegeräte"},{"k":"odd","q":"Was ist kein Hebegerät?","a":["Die Sackkarre","Der Brückenkran","Der Kettenzug","Der Hubtisch"],"ex":"Die Sackkarre dient zum Transport von Paketen am Boden.","ref":"Nicht im Kursmaterial · Förder- und Hebegeräte"},{"k":"case","s":"Vor dem Gebrauch des Gabelstaplers bemerken Sie ein Leck mit Hydrauliköl unter dem Gerät.","q":"Was tun Sie?","a":["Ich verwende ihn nicht und melde den Mangel","Ich verwende ihn vorsichtig, um den Tag zu beenden","Ich wische das Leck weg und verwende ihn","Ich melde es erst am nächsten Tag"],"ex":"Ein defektes Gerät wird bis zur Reparatur ausser Betrieb genommen.","ref":"Nicht im Kursmaterial · Förder- und Hebegeräte"},{"k":"qcm","q":"Wozu dient ein Scherenhubtisch im Wareneingang hauptsächlich?","a":["Die Last auf ergonomische Höhe bringen","Paletten über lange Strecken transportieren","Paletten auf sechs Meter Höhe stapeln","Lastwagen ohne Rampe direkt beladen"],"ex":"Er vermeidet Bücken und Armheben.","ref":"Nicht im Kursmaterial · Förder- und Hebegeräte"},{"k":"fill","q":"Ein am Brückenkran hängender ___ verteilt die Last auf mehrere Punkte.","a":["Hebebalken","Sackkarren","Handhubwagen","Hochhubwagen"],"ex":"Das ist der Hebebalken.","ref":"Nicht im Kursmaterial · Förder- und Hebegeräte"},{"k":"order","q":"Bringen Sie die Verwendung eines Hebegeräts in die richtige Reihenfolge.","a":["Das Gerät vor dem Gebrauch kontrollieren","Das Gewicht der Last prüfen","Die Last anschlagen oder aufnehmen","Heben und dabei die Zone überwachen","Die Last sanft absetzen"],"ex":"Kontrolle, Gewicht, Aufnahme, Heben, Absetzen.","ref":"Nicht im Kursmaterial · Förder- und Hebegeräte"},{"k":"case","s":"Ihr Unternehmen testet Exoskelette für die Kommissionierung. Ihres ist nicht richtig eingestellt und stört Sie.","q":"Was tun Sie?","a":["Ich lasse es auf meinen Körperbau einstellen","Ich trage es trotzdem, ohne etwas zu sagen","Ich leihe es einem grösseren Kollegen","Ich ziehe es so fest wie möglich an"],"ex":"Ein Exoskelett muss genau auf den Körperbau der Person eingestellt werden.","ref":"Nicht im Kursmaterial · SECO, «Exoskelette»"},{"k":"qcm","q":"Welche Angabe prüft man, bevor man eine Last mit einem Gerät hebt?","a":["Dass die Tragfähigkeit nicht überschritten wird","Die Farbe der Verpackung der Last oben","Den Namen des Lieferanten auf der Etikette","Die Zeit der nächsten Pause des Teams"],"ex":"Die Nenntragfähigkeit steht auf dem Typenschild des Geräts.","ref":"Nicht im Kursmaterial · Förder- und Hebegeräte"},{"k":"case","s":"Ein Kollege will mit dem Gabelstapler eine Person, die auf einer Palette steht, zu einem Regal hochheben.","q":"Was tun Sie?","a":["Ich lehne ab: Es braucht eine Arbeitsbühne","Ich sage zu, wenn er sich gut an den Masten hält","Ich sage zu, wenn ich die Palette sehr langsam hebe","Ich lasse ihn während meiner Pause allein machen"],"ex":"Ein Gabelstapler dient nie dazu, Personen auf einer Palette zu heben.","ref":"Nicht im Kursmaterial · Förder- und Hebegeräte"},{"k":"tf","q":"Hebehilfen verringern die körperlichen Belastungen im Wareneingang.","v":true,"ex":"Sie gehören zu den technischen Präventionsmassnahmen.","ref":"Lektion 3.6 · Nicht im Kursmaterial · Förder- und Hebegeräte"},{"k":"qcm","q":"Welches Gerät eignet sich am besten, um ein paar Kartons auf einem Trottoir zu einem Kunden zu bringen?","a":["Die Sackkarre","Der Brückenkran","Der Gabelstapler","Der Scherenhubtisch"],"ex":"Die Sackkarre ist leicht, wendig und kommt überall durch.","ref":"Nicht im Kursmaterial · Förder- und Hebegeräte"},{"k":"case","s":"Sie nehmen Säcke zu 25 kg entgegen. Ein Kollege schlägt einen im Lager verfügbaren Vakuumheber vor.","q":"Was halten Sie davon?","a":["Das ist eine gute Hebehilfe: Sie entlastet den Rücken","Das ist unnötig: 25 kg trägt man von Hand","Das ist gefährlich: Allein tragen ist besser","Das ist Lasten über einer Tonne vorbehalten"],"ex":"Hebehilfen verringern die Belastung auch bei wiederholten mittleren Lasten.","ref":"Nicht im Kursmaterial · Förder- und Hebegeräte · Nicht im Kursmaterial · Suva, «Heben und Tragen»"},{"k":"multi","q":"Welche Geräte sind im Wareneingang nützlich?","good":["Gabelstapler","Handhubwagen","Hubtisch","Brückenkran"],"bad":["Betonmischer","Rasenmäher"],"ex":"Diese Geräte entladen, verschieben und bringen die Waren auf Höhe.","ref":"Nicht im Kursmaterial · Förder- und Hebegeräte"},{"k":"case","s":"Eine Palette muss in einen Lastwagen ohne Verladerampe gestellt werden.","q":"Welches Mittel kann helfen?","a":["Die Hebebühne des Lastwagens","Allein die Sackkarre","Zwei Kollegen, die sie tragen","Ein Exoskelett"],"ex":"Die Hebebühne hebt die Palette auf die Höhe der Ladefläche.","ref":"Nicht im Kursmaterial · Förder- und Hebegeräte"},{"k":"qcm","q":"Welchen Körperteil entlastet ein Exoskelett für die Kommissionierung oft?","a":["Rücken oder Schulter","Augen und Gesicht","Ohren und der Nacken","Füsse und Knöchel"],"ex":"Exoskelette unterstützen vor allem Rücken oder Schultern.","ref":"Nicht im Kursmaterial · SECO, «Exoskelette»"}]},{"code":"D1.7","t":"Hilfsmittel","g":"Ich kenne verschiedene Hilfsmittel, um Waren ergonomisch und sicher einzulagern, und erkläre ihre Vorteile anhand eines Beispiels (Gabelstapler, Exoskelett, Sackkarre usw.). (K2)","col":"rose","ic":"dolly","ch":[{"k":"multi","q":"Welche Hilfsmittel nennt der Kurs, um Rückenschmerzen vorzubeugen?","good":["Scherenhubwagen","Gabelstapler"],"bad":["Improvisierte Leiter aus Kartons","Auf eine andere gelegte Palette"],"ex":"Der Kurs nennt Scherenhubwagen und Gabelstapler.","ref":"Lektion 3.6"},{"k":"qcm","q":"Was ist der Hauptvorteil eines Scherenhubwagens?","a":["Er hebt die Palette auf Arbeitshöhe","Er fährt schneller als ein Gabelstapler","Er stapelt Paletten auf 5 Meter","Er ersetzt die Sicherheitsschuhe"],"ex":"Er vermeidet tiefes Bücken beim Aufnehmen der Ware.","ref":"Lektion 3.6"},{"k":"case","s":"Sie müssen 30 Kartons zu 12 kg in ein Regal einräumen, auf Bodenhöhe und auf 1,80 m.","q":"Welches Mittel hilft Ihnen am meisten?","a":["Ein Scherenhubwagen oder ein Hubtisch","Eine improvisierte Leiter aus leeren Kartons","Zwei Kartons auf einmal tragen, um Zeit zu sparen","Die Kartons vom Boden aus aufs Regal werfen"],"ex":"Die Last auf gute Höhe zu bringen vermeidet Bücken und Armheben.","ref":"Lektion 3.6"},{"k":"qcm","q":"Wozu dient eine Sackkarre?","a":["Pakete auf zwei Rädern kippen und fahren","Ganze Paletten auf mehrere Meter Höhe heben","Eine Palette automatisch mit Stretchfolie umwickeln","Eine Ware bei der Ankunft im Wareneingang wägen"],"ex":"Die Sackkarre bewegt schwere Pakete, ohne sie zu tragen.","ref":"Nicht im Kursmaterial · Förder- und Hebegeräte"},{"k":"case","s":"Sie liefern 5 Kartons Wasser (je 9 kg) in den 1. Stock eines Büros, ohne Lift.","q":"Welches Hilfsmittel wählen Sie?","a":["Eine Treppensackkarre","Einen Gabelstapler","Einen elektrischen Handhubwagen","Keines: Ich trage alles in einem Gang"],"ex":"Die Treppensackkarre erspart das Tragen der Lasten mit ausgestreckten Armen.","ref":"Nicht im Kursmaterial · Förder- und Hebegeräte"},{"k":"match","q":"Ordnen Sie jedem Hilfsmittel seinen Vorteil zu.","p":[["Sackkarre","Pakete verschieben, ohne sie zu tragen"],["Scherenhubwagen","Auf guter Höhe arbeiten"],["Gabelstapler","Paletten in der Höhe einlagern"],["Exoskelett","Den Rücken bei wiederholten Bewegungen entlasten"]],"ex":"Jedes Mittel verringert eine bestimmte Belastung.","ref":"Lektion 3.6 · Nicht im Kursmaterial · Förder- und Hebegeräte"},{"k":"tf","q":"Ein Hilfsmittel zu verwenden dauert immer länger, als von Hand zu tragen.","v":false,"ex":"Richtig eingesetzt spart es oft Zeit und beugt Schmerzen vor.","ref":"Nicht im Kursmaterial · Suva, «Heben und Tragen»"},{"k":"sort","q":"Welches Hilfsmittel passt am besten?","c":["Sackkarre","Gabelstapler","Hubtisch"],"it":[["Getränkekisten in eine Bar liefern",0],["Eine Palette auf der 3. Ebene einlagern",1],["Eine Palette auf Arbeitshöhe auspacken",2],["Pakete auf ein Trottoir bringen",0],["Einen Lastwagen mit Paletten entladen",1],["Pakete verpacken, ohne sich zu bücken",2]],"ex":"Das richtige Mittel hängt von Last, Höhe und Weg ab.","ref":"Lektion 3.6 · Nicht im Kursmaterial · Förder- und Hebegeräte"},{"k":"case","s":"Der Handhubwagen steht am anderen Ende des Lagers. Ihr Kollege sagt: «Trag die 6 Kartons von Hand, das geht schneller.»","q":"Was tun Sie?","a":["Ich hole den Handhubwagen","Ich trage die 6 Kartons von Hand","Ich schiebe die Kartons mit dem Fuss über den Boden","Ich trage drei gestapelte Kartons auf einmal"],"ex":"Die verfügbaren Hilfsmittel zu nutzen, schützt den Rücken auf lange Sicht.","ref":"Lektion 3.6"},{"k":"qcm","q":"Warum lagert man schwere Artikel auf Hüfthöhe?","a":["Um sie ohne Bücken und ohne Armheben zu greifen","Damit sie vom Gang aus besser sichtbar sind","Um oben im Regal Platz zu sparen","Um das Zählen bei der Inventur zu erleichtern"],"ex":"Das ist eine ergonomische Lagerung.","ref":"Lektion 3.6 · Ergonomie"},{"k":"order","q":"Bringen Sie die Verwendung einer Sackkarre in die richtige Reihenfolge.","a":["Die Schaufel unter die Last schieben","Die Last an die Rückwand lehnen","Die Sackkarre zu sich kippen","Rollen und die Last stabil halten","Aufrichten und die Schaufel herausziehen"],"ex":"Man kippt, rollt, richtet auf: Die Last wird nie getragen.","ref":"Nicht im Kursmaterial · Förder- und Hebegeräte"},{"k":"odd","q":"Was ist kein Hilfsmittel für die Manipulation?","a":["Ein Cutter","Eine Sackkarre","Ein Handhubwagen","Ein Hubtisch"],"ex":"Der Cutter dient zum Öffnen, nicht zum Verschieben oder Heben.","ref":"Nicht im Kursmaterial · Förder- und Hebegeräte"},{"k":"case","s":"Sie kommissionieren Kleinteile an Regalen. Die schweren Behälter liegen ganz oben.","q":"Welche Verbesserung schlagen Sie vor?","a":["Die schweren Behälter auf Hüfthöhe lagern","Eine Leiter ohne Geländer ans Regal stellen","Direkt auf das Regal steigen","So lassen, man gewöhnt sich daran"],"ex":"Schwere Artikel lagert man zwischen Knien und Schultern.","ref":"Lektion 3.6 · Ergonomie"},{"k":"fill","q":"Der ___-Hubwagen hebt die Palette auf Arbeitshöhe.","a":["Scheren","Rollen","Arm","Hand"],"ex":"Der Scherenhubwagen.","ref":"Lektion 3.6"},{"k":"tf","q":"Ein Exoskelett kann den Rücken bei repetitiver Kommissionierung entlasten.","v":true,"ex":"Es unterstützt Rücken oder Schultern, ergänzend zu den anderen Massnahmen.","ref":"Nicht im Kursmaterial · SECO, «Exoskelette»"},{"k":"case","s":"Ein Kunde bittet Sie, eine Palette von 600 kg hinten in seiner Garage abzustellen. Sie haben nur einen Handhubwagen.","q":"Was tun Sie?","a":["Ich verwende den Handhubwagen und prüfe Boden und Weg","Ich zerlege die Palette und trage alles von Hand","Ich schiebe die Palette ohne Hilfsmittel über den Boden","Ich lasse sie wortlos vor dem Garagentor stehen"],"ex":"Der Handhubwagen bewegt die Palette am Boden; man prüft, ob der Boden eben und der Weg frei ist.","ref":"Nicht im Kursmaterial · Förder- und Hebegeräte"},{"k":"qcm","q":"Was ist der Vorteil eines Gabelstaplers beim Einlagern der Waren?","a":["Er lagert Paletten ohne körperliche Anstrengung hoch ein","Er ersetzt die Ausbildung des Personals ganz","Er kann von allen ohne Ausweis gefahren werden","Er ist leichter und wendiger als eine Sackkarre"],"ex":"Er stapelt schwere Paletten in die Höhe.","ref":"Lektion 3.6"},{"k":"case","s":"Sie müssen eine Palette von 900 kg auf der 3. Ebene einlagern. Sie haben keine Staplerausbildung.","q":"Was tun Sie?","a":["Ich bitte einen ausgebildeten Kollegen","Ich fahre den Stapler sehr langsam","Ich lade die Palette von Hand Stück für Stück ab","Ich lasse die Palette im Gang stehen"],"ex":"Nur ausgebildete und ermächtigte Personen fahren einen Gabelstapler.","ref":"Nicht im Kursmaterial · Förder- und Hebegeräte"},{"k":"multi","q":"Welches sind die Vorteile von Hilfsmitteln?","good":["Weniger körperliche Anstrengung","Weniger Rückenschmerzen","Weniger Unfallrisiken","Oft schnellere Arbeit"],"bad":["Keine Ausbildung mehr nötig","Keine PSA mehr nötig"],"ex":"Sie verringern Belastungen und Risiken.","ref":"Lektion 3.6 · Nicht im Kursmaterial · Suva, «Heben und Tragen»"},{"k":"case","s":"Ihre Sackkarre hat einen platten Reifen.","q":"Was tun Sie?","a":["Ich melde es und nehme eine andere Sackkarre","Ich verwende sie trotzdem und ziehe kräftig","Ich trage die Pakete stattdessen wortlos","Ich versorge sie und hoffe, dass sie jemand repariert"],"ex":"Ein defektes Hilfsmittel wird selbst zur Gefahr.","ref":"Nicht im Kursmaterial · Förder- und Hebegeräte"},{"k":"qcm","q":"Mit welchem Hilfsmittel kann man an einer tiefen Palette arbeiten, ohne sich zu bücken?","a":["Der Hubtisch","Die Sackkarre","Der Plattformwagen","Der Sicherheitscutter"],"ex":"Er bringt die Palette auf Arbeitshöhe.","ref":"Nicht im Kursmaterial · Förder- und Hebegeräte"},{"k":"case","s":"Ihr Unternehmen bittet Sie, einen Monat lang ein Exoskelett zu testen.","q":"Welche Haltung nehmen Sie ein?","a":["Ich teste es und melde, was hilft oder stört","Ich weigere mich einfach, es auszuprobieren","Ich trage es nur, wenn der Chef zuschaut","Ich hebe schwerer, weil ich ja unterstützt werde"],"ex":"Die Meinung der Benutzenden hilft zu entscheiden, ob das Exoskelett zur Aufgabe passt.","ref":"Nicht im Kursmaterial · SECO, «Exoskelette»"},{"k":"tf","q":"Eine ergonomische Lagerung legt leichte Artikel nach oben und schwere auf Hüfthöhe.","v":true,"ex":"Die Randzonen (Boden, über den Schultern) sind leichten oder wenig gefragten Artikeln vorbehalten.","ref":"Lektion 3.6 · Ergonomie"},{"k":"qcm","q":"Welches Mittel wählt man, um Kartons in einen Lastwagen ohne Rampe zu bringen?","a":["Die Hebebühne","Die Sackkarre auf der Rampe","Mit ausgestreckten Armen tragen","Die Kartons in den Lastwagen werfen"],"ex":"Die Hebebühne hebt die Last bis auf die Ladefläche.","ref":"Nicht im Kursmaterial · Förder- und Hebegeräte"},{"k":"case","s":"Sie lagern den ganzen Morgen Stretchfolienrollen zu 17 kg einzeln ein.","q":"Welche Lösung ist am sichersten?","a":["Einen Wagen oder Tisch auf guter Höhe nutzen","Sie zu zweit tragen, um schneller zu sein","Sie mit dem Fuss über den Boden rollen","Sie vom Gang aus auf das Regal werfen"],"ex":"Auch eine mittlere Last verlangt ein Hilfsmittel, wenn sie den ganzen Morgen wiederholt wird.","ref":"Nicht im Kursmaterial · Suva, «Heben und Tragen»"}]}];
